```python
class Proxy:
    def __init__(self, proxy_url):
        self.proxy_url = proxy_url

    def get(self, *args, **kwargs):
        # 使用 CaseInsensitiveDict 来处理 URL 参数
        return requests.get(self.proxy_url, **CaseInsensitiveDict(*args, **kwargs))

    def send(self, url, *args, **kwargs):
        # 使用 get 方法发送请求
        response = requests.get(url, headers=self.proxy_url)
        return response.json()

# 示例
